contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other, uint256 deposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= deposit, "insufficient test balance");

        uint256 preOther = c.balances(other); if (__ESBMC_reverted()) return;
        uint256 preCaller = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 preReserve = address(c).balance;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted || (c.balances(other) == preOther && address(c).balance == preReserve - preCaller));
    }

    receive() external payable {}
}

