pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    keepMyEther c;

    function setUp() public {
        c = new keepMyEther();
    }

    function _run(address other, uint256 deposit) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= deposit);
        uint256 preOther;
        try c.balances(other) returns (uint256 __r) { preOther = __r; } catch { return; }
        uint256 preCaller;
        try c.balances(address(this)) returns (uint256 __r) { preCaller = __r; } catch { return; }
        uint256 preReserve = address(c).balance;
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted || (c.balances(other) == preOther && address(c).balance == preReserve - preCaller));
    }

    function testFuzz_run(address other, uint256 deposit) public {
        vm.assume(other.code.length == 0 && uint160(other) > 0xffff && other != address(this) && other != address(c) && other != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && other != 0x000000000000000000636F6e736F6c652e6c6f67 && other != 0x4e59b44847b379578588920cA78FbF26c0B4956C && other != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(other, deposit);
    }

